export const characterEnrichment = Object.fromEntries(residents.map(([slug,weeklyGoal,ambition,ordinaryWish,relationshipTension,privateConcern,age1,event1,age2,event2,action,line]) => [slug,{weeklyGoal,ambition,ordinaryWish,relationshipTension,privateConcern,milestones:[{age:age1,event:event1},{age:age2,event:event2}],firstMeeting:{action,line}}]));

export const chronology = {
  presentYear:38, landingYear:0, lyraEmergencyYear:20,
  renewal:'The Lyra emergency and associated renewal of the founding agreement occurred in Year 20, eighteen years before the present. Naomi was 28, Malik 21, Luc 33, Jonah 24 and Rhea 22. They were not adult decision-makers at first landing.',
  missingHours:'The seventeen missing hours belong to Year 0. They remain separate from Year 20 unless evidence in a player’s story establishes a limited connection.',
  origin:'Earth-derived heritage labels describe author-facing ancestry and inherited family culture, not personal familiarity with modern Earth countries. Home means belonging, not necessarily birthplace. Do not invent a named off-world birthplace when it is unspecified.',
};

export function enrichCharacter(character) {
  const entry=characterEnrichment[character.slug];
  if(!entry)throw new Error(`Missing enrichment for ${character.slug}`);
  const bornYear=38-character.age;
  const origin=bornYear>=0
    ?{birthplace:'Eos Meridian',birthYear:bornYear,arrivalYear:null,bornOnEos:true}
    :{birthplace:'Off-world; specific birthplace unrecorded',birthYear:bornYear,arrivalYear:0,bornOnEos:false};
  return {
    ...entry, origin,
    milestones:[{year:bornYear,event:bornYear>=0?'Born in Eos Meridian.':'Born off-world before the Meridian landing.'},...entry.milestones.map(({age,event})=>({year:bornYear+age,age,event}))],
    knowledgeDiscipline:'Personal concerns are private until disclosed in this conversation. Other residents know only what they witnessed, were told, or learned publicly. A shared scene does not share private disclosures. Do not reveal the mystery hook by default.',
    scenePractice:{repeat:'Follow up on the weekly goal only if it is relevant and has not already been resolved in this conversation.',friendship:entry.ordinaryWish,group:entry.relationshipTension,repair:'Name the specific harm, ask what repair is welcome, and let trust change through later action. Do not resolve another person’s grievance for them.'},
    continuity:'Goals and concerns describe the starting situation. Established player-session decisions and memories take precedence over this starting state. Never undo a completed choice or assert a proposal already happened. Ordinary evenings may remain ordinary; friendship needs no romantic escalation.',
  };
}

