/** Use the existing location-lore retrieval fields, not an unread parallel bible. */
export function editorialLocationLore(place){
  const life=place.editorialLife??{};
  return {
    publicHistory:life.pastIncident?[life.pastIncident]:[],
    conversationHooks:[life.regular,life.disputedUse,life.disagreement,life.habit].filter(Boolean),
    localEtiquette:life.unwrittenRule?[life.unwrittenRule]:[],
    storySeeds:life.changingCondition?[life.changingCondition]:[],
    recurringPeople:(place.supportingResidents??[]).map(person=>({label:person.name,role:person.role,rhythm:`${person.goal} ${person.principle} ${person.knowledge}`})),
  };
}
